// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;

    receive() external payable {}

    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, type(uint128).max);
        address depositor = makeAddr("depositor");
        vm.deal(depositor, amount);
        vm.prank(depositor);
        (bool ok, ) = address(c).call{value: amount}("");
        assertTrue(ok);

        vm.prank(address(this)); // c's owner (deployer) is this test contract
        c.withdrawAll();

        assertTrue(address(c).balance == 0);
    }
}
